mapper.select:
SELECT * FROM f_bonus
WHERE applicant = #{applicant}

    AND approval_status = #{status}

ORDER BY application_time DESC

mapper.insert:
INSERT INTO f_bonus (
    belong, amount, reason, img,
    approval_status, application_time,
    applicant, employee_id, category
) VALUES (
             #{belong}, #{amount}, #{reason}, #{img},
             0, NOW(),
             #{applicant}, #{employeeId},#{category}
         )

